        "prompt": "提示词：\n\n为场景创建一张单独的艺术海报。严格单独输出——切勿组合场景或创建拼贴画。\n\n格式\n使用严格的 4:5 纵向构图。整个画面覆盖温暖的米白色陈旧纸张，带有细微纤维、自然纸张纹理、轻微磨损和哑光触感质感。保留大量的空白留白空间。\n\n戳印艺术作品\n创建一张紧凑的多色雕刻橡胶戳（橡皮图章印章艺术），描绘【十二生肖之灵犬】：忠诚守望的灵犬轮廓、竖耳昂首、欢快卷尾与几穗麦芒。\n极度简化。只保留瞬间识别十二生肖之灵犬所需的可视形态。移除无关复杂细节与杂乱背景。\n\n将橡胶戳置于画面中心或中下部，占据约 30–38% 的画面高度，周围留有充足干净的米白色纸张空白空间。保持其紧凑、质朴且低调——绝非全景插图或超大图形。\n\n墨水与纹理\n使用 2–3 种受传统印章启发的柔和专色，如炭黑、赭黄、砖红。\n为每种颜色赋予单独的手工戳印层，带有真实的雕刻橡胶瑕疵：雕刻刀痕、不均匀线条、缺口边缘、干墨间隙、纸张透印、颗粒墨水、不均匀按压力道和细微错位。\n结果必须感觉像真实的橡胶戳印章压印在陈旧米白纸张上。\n\n纯粹印章画面（无任何文字）\n整张图只有纸张与中间的橡胶戳印图案，画面中绝对不要出现任何文字、字母、汉字、数字、年份、排版、标签或边框文字。\n\n避免\n文字、字母、汉字、数字、边框文字、排版、拼贴画、圆形红色公章、邮票齿孔、蜡封、贴纸、平滑矢量标志、卡通3D渲染、光泽渐变、塑料质感、过多细节与装饰杂乱。",
